#[derive(Queryable)]
#[diesel(table_name = payments)]
struct PaymentRow { id: i32, name: String, kind: String, card_number: Option<String> }

fn map_payment(r: PaymentRow) -> Payment {
    match r.kind.as_str() {                 // discriminator -> enum variant
        "card" => Payment::Card { card_number: r.card_number.unwrap_or_default() },
        "transfer" => Payment::Transfer { account: r.name.clone() },
        _ => Payment::Base { id: r.id, name: r.name },
    }
}
